Analyzing the demo: the grid is split by a constant column (7s). Left half (marker 2) and right half (marker 5) combine: output column j is 0 if left col j has a marker OR right col (j+sep+1) has a marker, else 3 (fill).

```python
from collections import Counter

def transform(grid):
    H, W = len(grid), len(grid[0])
    # find separator column: fully constant, and constant value differs from most cells elsewhere
    sep = None
    for c in range(W):
        vals = {grid[r][c] for r in range(H)}
        if len(vals) == 1:
            v = grid[0][c]
            others = Counter(grid[r][c2] for r in range(H) for c2 in range(W) if c2 != c)
            if others.get(v, 0) == 0 and len(others) > 0:
                sep = c
                break
    if sep is None:
        sep = W // 2
    lw = sep
    rw = W - sep - 1
    outw = min(lw, rw) if lw != rw else lw
    # actually demo: lw == rw == outw; test likely lw == rw too
    def marker(cols):
        cnt = Counter(grid[r][c] for r in range(H) for c in cols)
        return cnt.most_common()[-1][0]
    lm = marker(range(sep))
    rm = marker(range(sep + 1, W))
    out = []
    for r in range(H):
        row = []
        for j in range(outw):
            zero = False
            if j < lw and grid[r][j] == lm:
                zero = True
            if sep + 1 + j < W and grid[r][sep + 1 + j] == rm:
                zero = True
            row.append(0 if zero else 3)
        out.append(row)
    return out
